const fs = require('fs');
const zlib = require('zlib');

const DIR = '/backups';
const PREFIX = 'rayuela_';
const SUFFIX = '.sql.gz';
const MAX_AGE_HOURS = 4;
const MIN_BYTES = 1;
const SQL_END_MARKER = 'PostgreSQL database dump complete';

function humanSize(bytes) {
  if (bytes === null || bytes === undefined) return null;
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let value = Number(bytes);
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit += 1;
  }
  return `${value.toFixed(unit === 0 ? 0 : 2)} ${units[unit]}`;
}

async function inspectGzip(filePath) {
  return await new Promise((resolve) => {
    let bytes = 0;
    let tail = '';
    let settled = false;

    const finish = (result) => {
      if (settled) return;
      settled = true;
      resolve(result);
    };

    const source = fs.createReadStream(filePath);
    const gunzip = zlib.createGunzip();

    source.on('error', (error) => finish({ ok: false, error: error.message, bytes: 0, tail: '' }));
    gunzip.on('error', (error) => finish({ ok: false, error: error.message, bytes, tail }));
    gunzip.on('data', (chunk) => {
      bytes += chunk.length;
      tail = (tail + chunk.toString('utf8')).slice(-8192);
    });
    gunzip.on('end', () => finish({ ok: true, error: null, bytes, tail }));

    source.pipe(gunzip);
  });
}

const now = Date.now();
let estado = 'OK';
let motivo = null;
let detalle = '';
let archivo = null;
let ruta = null;
let tamanoBytes = null;
let tamanoHumano = null;
let edadHoras = null;
let gzipOk = null;
let dumpCompleto = null;
let bytesDescomprimidos = null;
let cantidadArchivos = 0;
let ultimoMtime = null;

try {
  const entries = fs.existsSync(DIR) ? fs.readdirSync(DIR) : [];
  const candidatos = entries
    .filter((name) => name.startsWith(PREFIX) && name.endsWith(SUFFIX))
    .map((name) => {
      const fullPath = `${DIR}/${name}`;
      const stats = fs.statSync(fullPath);
      return { name, fullPath, stats };
    })
    .filter((item) => item.stats.isFile());

  cantidadArchivos = candidatos.length;

  if (cantidadArchivos === 0) {
    estado = 'FALLO';
    motivo = 'SIN_BACKUPS';
    detalle = 'No se encontraron archivos rayuela_*.sql.gz en /backups';
  } else {
    candidatos.sort((a, b) => b.stats.mtimeMs - a.stats.mtimeMs);
    const ultimo = candidatos[0];
    archivo = ultimo.name;
    ruta = ultimo.fullPath;
    tamanoBytes = ultimo.stats.size;
    tamanoHumano = humanSize(tamanoBytes);
    edadHoras = Number(((now - ultimo.stats.mtimeMs) / 3600000).toFixed(2));
    ultimoMtime = new Date(ultimo.stats.mtimeMs).toISOString();

    const motivos = [];

    if (tamanoBytes < MIN_BYTES) {
      motivos.push('ARCHIVO_VACIO');
    }

    if (edadHoras > MAX_AGE_HOURS) {
      motivos.push('BACKUP_VIEJO');
    }

    if (tamanoBytes >= MIN_BYTES) {
      const gzip = await inspectGzip(ruta);
      gzipOk = gzip.ok;
      bytesDescomprimidos = gzip.bytes;
      dumpCompleto = gzip.ok && gzip.tail.includes(SQL_END_MARKER);

      if (!gzip.ok) {
        motivos.push('GZIP_INVALIDO');
      } else if (bytesDescomprimidos < MIN_BYTES) {
        motivos.push('DUMP_VACIO');
      } else if (!dumpCompleto) {
        motivos.push('DUMP_INCOMPLETO');
      }
    }

    if (motivos.length > 0) {
      estado = 'FALLO';
      motivo = motivos.join(',');
      detalle = `Backup ${archivo}: ${motivo}`;
    } else {
      detalle = `Backup OK: ${archivo} (${tamanoHumano}, ${edadHoras} h)`;
    }
  }
} catch (error) {
  estado = 'FALLO';
  motivo = 'ERROR_VALIDACION';
  detalle = `Error validando backups: ${error.message}`;
}

const result = {
  estado,
  motivo,
  detalle,
  archivo,
  ruta,
  tamanoBytes,
  tamanoHumano,
  edadHoras,
  gzipOk,
  dumpCompleto,
  bytesDescomprimidos,
  cantidadArchivos,
  ultimoMtime,
  verificadoEn: new Date().toISOString(),
  directorio: DIR,
};

if (estado === 'FALLO') {
  console.error(JSON.stringify({ source: 'n8n-fl2-validar-backup', ...result }, null, 2));
} else {
  console.log(JSON.stringify({ source: 'n8n-fl2-validar-backup', ...result }, null, 2));
}

return [{ json: result }];

const sourceItems = $input.all();
const rows = sourceItems.map((item) => {
  const data = item.json || {};
  const log = {
    ts: new Date().toISOString(),
    source: 'n8n-fl2-resultado',
    workflow: $workflow.name,
    executionId: $execution.id,
    estado: data.estado || null,
    motivo: data.motivo || null,
    archivo: data.archivo || null,
    tamanoBytes: data.tamanoBytes ?? null,
    edadHoras: data.edadHoras ?? null,
    gzipOk: data.gzipOk ?? null,
    dumpCompleto: data.dumpCompleto ?? null,
    detalle: data.detalle || null,
  };

  if (data.estado === 'FALLO') {
    console.error(JSON.stringify(log, null, 2));
  } else {
    console.log(JSON.stringify(log, null, 2));
  }

  return item;
});
return rows;

